mapper.select:
SELECT pt.trip_id tripId, pt.`start`, pt.destination,
        DATE_FORMAT(pt.start_time, '%Y年%c月%e日 %H:%i') startTime,
        DATE_FORMAT(pt.end_time, '%Y年%c月%e日 %H:%i') endTime,
        DATE_FORMAT(pt.create_time, '%Y年%c月%e日 %H:%i') createTime,
        pc.license, pc.brand, pc.model
FROM pubcar_trip pt
LEFT JOIN pubcar_trip_car_num ptcn ON ptcn.trip_id = pt.trip_id AND ptcn.status_cd = '0'
LEFT JOIN pubcar_car pc ON pc.car_id = ptcn.car_id AND pc.status_cd = '0'
WHERE pt.status_cd = '0'

    AND pt.user_id = #{userId}


    AND pt.trip_status= #{tripStatus}


    AND pt.approval_status= #{approvalStatus}


    AND pt.community_id = #{communityId}

ORDER BY pt.create_time DESC

    limit #{page}, #{row}

SELECT COUNT(*)
FROM pubcar_trip
WHERE status_cd = '0'

    AND user_id = #{userId}


    AND trip_status= #{tripStatus}


    AND approval_status= #{approvalStatus}


    AND community_id = #{communityId}

SELECT ptcr.driver_id driverId, pt.user_id userId
FROM pubcar_trip_car_num ptcr
LEFT JOIN pubcar_trip pt ON ptcr.trip_id = pt.trip_id
WHERE ptcr.car_id = #{carId}
AND DATE(pt.start_time) <= #{violationTime}
AND DATE(pt.end_time) >= #{violationTime}
AND pt.community_id = #{communityId}
AND pt.status_cd = '0'

SELECT trip_id tripId, `start`, destination, mileage, start_time startTime, end_time endTime, apply_num applyNum,
       trip_status tripStatus, approval_status approvalStatus, is_bureau_leader_approve isBureauLeaderApprove, remark, apply_reason applyReason, is_urgent isUrgent,
       is_daily isDaily, daily_period dailyPeriod, user_id userId, b_id bId, status_cd statusCd, community_id communityId
FROM pubcar_trip


        b_id = #{bId}


        and status_cd = #{statusCd}

SELECT count(1) count
FROM pubcar_trip t
LEFT JOIN pubcar_trip_car_num n ON n.trip_id = t.trip_id
LEFT JOIN pubcar_driver d ON d.driver_id = n.driver_id
LEFT JOIN pubcar_car c ON c.car_id = n.car_id
WHERE t.status_cd = '0' AND t.approval_status = 3
/*今天*/

    AND DATE(t.start_time) = CURRENT_DATE()

/*明天*/

    AND DATE(t.start_time) = CURRENT_DATE() + 1

/*未来7天*/

     AND DATEDIFF(DATE(t.start_time), CURRENT_DATE()) >= 0 AND DATEDIFF(DATE(t.start_time), CURRENT_DATE()) <= 7 


    and t.community_id = #{communityId}

SELECT t.trip_id tripId, t.start_time departureTime, t.`start` departure, t.destination, n.trip_type tripType, c.model, c.license, d.`name` driver, t.user_id userId
FROM pubcar_trip t
LEFT JOIN pubcar_trip_car_num n ON n.trip_id = t.trip_id
LEFT JOIN pubcar_driver d ON d.driver_id = n.driver_id
LEFT JOIN pubcar_car c ON c.car_id = n.car_id
WHERE t.status_cd = '0' AND t.approval_status = 3
/*今天*/

    AND DATE(t.start_time) = CURRENT_DATE()

/*明天*/

    AND DATE(t.start_time) = CURRENT_DATE() + 1

/*未来7天*/

     AND DATEDIFF(DATE(t.start_time), CURRENT_DATE()) >= 0 AND DATEDIFF(DATE(t.start_time), CURRENT_DATE()) <= 7 


    and t.community_id = #{communityId}

ORDER BY t.start_time DESC

    limit #{page}, #{row}

SELECT IFNULL(MAX(b.count), 0) peakSingleDayCar,
        IFNULL(ROUND(AVG(b.count)), 0) averageTripsPerDay
FROM (
    SELECT DATE(a.start_time) dayGroup, count(1) count
    FROM pubcar_trip a
    WHERE a.status_cd = '0' and a.approval_status = 3

        and a.community_id = #{communityId}


         and DATE(a.start_time) >= #{startTime}


         and DATE(a.end_time) <= #{endTime}

    GROUP BY DATE(a.start_time)
) b

SELECT t.trip_id, COUNT(DISTINCT t.trip_id) tripNum, IFNULL(ROUND(SUM(a.avgMileage),1), 0) tripMileage, IFNULL(ROUND(SUM(a.avgDuration)), 0) drivingTime, IFNULL(ROUND(AVG(a.avgMileage),1), 0) averageMileage, IFNULL(ROUND(AVG(a.avgDuration)), 0) averageTravelTime FROM pubcar_trip t LEFT JOIN ( SELECT trip_id, AVG(pass_mileage) avgMileage, AVG(duration) avgDuration FROM pubcar_trip_mileage GROUP BY trip_id ) a ON a.trip_id = t.trip_id WHERE t.status_cd = '0' and t.trip_status = 3
and t.community_id = #{communityId}
and t.start_time >= #{startTime}
and t.end_time <= #{endTime}

SELECT t.trip_id tripId, uu.`name` applicant, t.`start`, t.destination, t.start_time startTime, t.end_time endTime,
       n.is_self isSelf, n.passenger_num passengerNum, d.`name` driver, m.pass_mileage drivenDistance, m.duration drivingTime
FROM pubcar_trip t
LEFT JOIN u_user uu ON uu.user_id = t.user_id AND uu.status_cd = '0'
LEFT JOIN pubcar_trip_car_num n ON n.trip_id = t.trip_id
LEFT JOIN pubcar_car c ON c.car_id = n.car_id AND c.status_cd = '0'
LEFT JOIN pubcar_driver d ON d.driver_id = n.driver_id AND d.status_cd = '0'
LEFT JOIN pubcar_trip_mileage m ON m.trip_id = n.trip_id AND m.driver_id = n.driver_id AND m.status_cd = '0'
WHERE t.status_cd = '0'
  AND c.car_id =  #{carId}
  AND t.community_id = #{communityId}

    and uu.name like concat('%',#{applicant},'%')


    and d.name like concat('%',#{driver},'%')


    and n.trip_type = #{tripType}


     and m.start_time >= #{lessStartTime}


     and m.start_time <= #{moreStartTime}


     and m.end_time >= #{lessEndTime}


     and m.end_time <= #{moreEndTime}

order by t.create_time desc

    limit #{page}, #{row}

SELECT COUNT(1) count
FROM pubcar_trip t
LEFT JOIN u_user uu ON uu.user_id = t.user_id AND uu.status_cd = '0'
LEFT JOIN pubcar_trip_car_num n ON n.trip_id = t.trip_id
LEFT JOIN pubcar_car c ON c.car_id = n.car_id AND c.status_cd = '0'
LEFT JOIN pubcar_driver d ON d.driver_id = n.driver_id AND d.status_cd = '0'
LEFT JOIN pubcar_trip_mileage m ON m.trip_id = n.trip_id AND m.driver_id = n.driver_id AND m.status_cd = '0'
WHERE t.status_cd = '0'
    AND c.car_id = #{carId}
    AND t.community_id = #{communityId}

    and uu.name like concat('%',#{applicant},'%')


    and d.name like concat('%',#{driver},'%')


    and n.trip_type = #{tripType}


     and m.start_time >= #{lessStartTime}


     and m.start_time <= #{moreStartTime}


     and m.end_time >= #{lessEndTime}


     and m.end_time <= #{moreEndTime}

SELECT t.trip_id tripId, uu.name applicant, t.start, t.destination, m.start_time startTime, m.end_time endTime, n.is_self isSelf, t.apply_num applyNum, c.license, m.duration drivingTime, t.create_time createTime
FROM pubcar_trip t
LEFT JOIN pubcar_trip_mileage m ON m.trip_id = t.trip_id
LEFT JOIN pubcar_trip_car_num n ON m.driver_id = n.driver_id AND n.trip_id = m.trip_id
LEFT JOIN pubcar_car c ON c.car_id = n.car_id
LEFT JOIN u_user uu ON uu.user_id = t.user_id
LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id
LEFT JOIN u_org uo ON uo.org_id = uosr.org_id
WHERE t.trip_status = 3 and t.status_cd = '0' and m.status_cd = '0' and c.status_cd = '0' and uu.status_cd = '0' and uosr.status_cd = '0' and uo.status_cd = '0'

    and uu.name like concat('%',#{applicant},'%')


    and t.start like concat('%',#{start},'%')


    and t.destination like concat('%',#{destination},'%')


     and t.start_time >= #{startTime}


     and t.end_time <= #{endTime}


    and c.license like concat('%',#{license},'%')


    and t.apply_num = #{applyNum}


    and m.driver_id = #{driverId}


    and uo.org_id = #{departmentId}

order by t.create_time desc

    limit #{page}, #{row}

SELECT COUNT(1) count FROM pubcar_trip t LEFT JOIN pubcar_trip_mileage m ON m.trip_id = t.trip_id LEFT JOIN pubcar_trip_car_num n ON m.driver_id = n.driver_id AND n.trip_id = m.trip_id LEFT JOIN pubcar_car c ON c.car_id = n.car_id LEFT JOIN u_user uu ON uu.user_id = t.user_id LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id LEFT JOIN u_org uo ON uo.org_id = uosr.org_id WHERE t.trip_status = 3 and t.status_cd = '0' and m.status_cd = '0' and c.status_cd = '0' and uu.status_cd = '0' and uosr.status_cd = '0' and uo.status_cd = '0'
and uu.name like concat('%',#{applicant},'%')
and t.start like concat('%',#{start},'%')
and t.destination like concat('%',#{destination},'%')
and t.start_time >= #{startTime}
and t.end_time <= #{endTime}
and c.license like concat('%',#{license},'%')
and t.apply_num = #{applyNum}
and m.driver_id = #{driverId}
and uo.org_id = #{departmentId}

select b_id bId, trip_id tripId, user_id userId, car_type carType, `start`, destination, start_time startTime, end_time endTime, apply_num applyNum, trip_status tripStatus, approval_status approvalStatus, is_bureau_leader_approve isBureauLeaderApprove, is_depart_leader_approve isDepartLeaderApprove, remark, apply_reason applyReason,is_urgent isUrgent, is_daily isDaily, daily_period dailyPeriod, operate, community_id communityId, car_type_detail carTypeDetail from business_pubcar_trip
b_id= #{bId}
and operate= #{operate}

mapper.insert:
insert into pubcar_trip(b_id, trip_id, user_id, car_type, car_type_detail, `start`, destination, mileage, start_time, end_time, apply_num, trip_status, approval_status, apply_reason, is_urgent, is_daily, daily_period, status_cd, community_id) select b_id, trip_id, user_id, car_type, car_type_detail, `start`, destination, mileage, start_time, end_time, apply_num, trip_status, approval_status, apply_reason, is_urgent, is_daily, daily_period, '0', community_id from business_pubcar_trip
b_id= #{bId}
and operate= #{operate}

mapper.select:
SELECT t.trip_id tripId, t.start, t.destination, t.start_time startTime, t.end_time endTime, t.apply_num applyNum, t.trip_status tripStatus, t.approval_status approvalStatus, t.is_bureau_leader_approve isBureauLeaderApprove, t.remark, t.apply_reason applyReason, t.is_urgent isUrgent, t.is_daily isDaily, t.daily_period dailyPeriod, t.create_time applicationTime, t.is_depart_leader_approve isDepartLeaderApprove, t.user_id applicantId, uu.name applicant, uu.tel, uo.org_name department, d.name `position`, n.num_id numId, n.trip_type tripType, n.passenger_num passengerNum, p.passenger_id passengerId, p.passenger_name passengerName, p.passenger_department passengerDepartment, p.passenger_position passengerPosition, n.car_id carId,n.driver_id driverId, n.no, t.car_type carType, ptm.start_mileage startMileage, ptm.end_mileage endMileage, ptm.pass_mileage passMileage, ptm.run_range runRange, ptm.repair_fee repairFee, ptm.oil_fee oilFee, ptm.parking_fee parkingFee, ptm.road_bridge_fee roadBridgeFee FROM pubcar_trip t LEFT JOIN pubcar_trip_car_num n on n.trip_id = t.trip_id LEFT JOIN pubcar_trip_car_passenger p on p.num_id = n.num_id LEFT JOIN pubcar_trip_mileage ptm ON ptm.trip_id = n.trip_id AND ptm.driver_id = n.driver_id LEFT JOIN u_user uu ON uu.user_id = t.user_id AND uu.status_cd = '0' LEFT JOIN u_org_staff_rel r ON r.staff_id = uu.user_id AND r.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = r.org_id AND uo.status_cd = '0' LEFT JOIN t_dict d ON d.status_cd = r.rel_cd AND d.table_name = 'u_org_staff_rel' AND d.table_columns = 'rel_cd' WHERE t.status_cd= '0' and t.trip_id in ( select temp.id from( select t.trip_id id from pubcar_trip t LEFT JOIN ( SELECT trip_id, GROUP_CONCAT(trip_type SEPARATOR ',') tripType FROM pubcar_trip_car_num GROUP BY trip_id ) n ON n.trip_id = t.trip_id LEFT JOIN u_user uu ON uu.user_id = t.user_id AND uu.status_cd = '0' LEFT JOIN u_org_staff_rel r ON r.staff_id = uu.user_id AND r.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = r.org_id AND uo.status_cd = '0' LEFT JOIN t_dict d ON d.status_cd = r.rel_cd AND d.table_name = 'u_org_staff_rel' AND d.table_columns = 'rel_cd' WHERE t.status_cd= '0'
and t.user_id = #{userId}
and uu.name like concat('%',#{applicant},'%')
and uu.tel like concat('%',#{tel},'%')
and t.start like concat('%',#{start},'%')
and t.destination like concat('%',#{destination},'%')
and t.apply_num= #{applyNum}
and t.is_urgent= #{isUrgent}
and uo.org_name like concat('%',#{department},'%')
and d.name like concat('%',#{position},'%')
and n.tripType = #{tripType}
and t.trip_status= #{tripStatus}
and t.approval_status= #{approvalStatus}
and t.start_time >= #{applyTimeStart}
and t.end_time <= #{applyTimeEnd}
and t.trip_id= #{tripId}
and t.trip_id in
#{item}
and t.community_id= #{communityId}
order by
start_time ${sort},
t.create_time desc
limit #{page}, #{row}
) as temp )

SELECT t.trip_id tripId, t.start, t.destination, t.start_time startTime, t.end_time endTime, t.apply_num applyNum, t.trip_status tripStatus, t.approval_status approvalStatus, t.create_time applicationTime, uu.name applicant, n.num_id numId, n.trip_type tripType,n.passenger_num passengerNum,n.driver_id driverId, p.passenger_id passengerId, p.passenger_name passengerName, n.car_id carId FROM pubcar_trip t LEFT JOIN pubcar_trip_car_num n ON n.trip_id = t.trip_id LEFT JOIN pubcar_trip_car_passenger p ON p.num_id = n.num_id LEFT JOIN u_user uu ON uu.user_id = t.user_id AND uu.status_cd = '0' WHERE t.status_cd= '0' AND t.trip_id IN ( SELECT temp.id FROM( SELECT t.trip_id id FROM pubcar_trip t LEFT JOIN pubcar_trip_car_num n ON n.trip_id = t.trip_id LEFT JOIN pubcar_trip_car_passenger p ON p.num_id = n.num_id WHERE t.status_cd= '0' AND t.approval_status = 3
and (p.user_id = #{driverId} or t.user_id = #{driverId})
and (t.trip_status = 1 or t.trip_status = 2)
and t.trip_status = 3
and t.community_id = #{communityId}
ORDER BY t.trip_status DESC, t.create_time DESC
limit #{page}, #{row}
) AS temp ) ORDER BY t.trip_status DESC, t.create_time DESC

